// streamsItem seeds an item shaped for the streams lane: a settled `ready`
// metadata record (sources + _stages populated) whose parsed carries the
// absolute_path stamp the pack seam consumes. Returned with its row.
func streamsItem(t *testing.T, s *store.Store, libID int64, id string) store.Item {
	t.Helper()
	doc := baseDoc("Movies/Hostile Container.mkv")
	doc["parsed"].(map[string]any)["absolute_path"] = "/library/Movies/Hostile Container.mkv"
	doc["ffprobe"] = map[string]any{"format": map[string]any{"duration": "12.0"}}
	doc["sources"] = map[string]any{"tv-parser": map[string]any{"title": "done"}}
	doc["_stages"] = []map[string]any{{"stage": "metadata_source", "plugin_id": "tv-parser", "status": "ok"}}
	putItem(t, s, id, libID, statusReady, doc)
	it, err := s.GetItem(context.Background(), id, access.System())
	if err != nil {
		t.Fatalf("GetItem %s: %v", id, err)
	}
	return it
}

// streamsState polls the item until doc["streams"].state is want (or fails).
func streamsState(t *testing.T, s *store.Store, id, want string, timeout time.Duration) map[string]any {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		it, err := s.GetItem(context.Background(), id, access.System())
		if err == nil {
			var doc map[string]any
			_ = json.Unmarshal(it.Document, &doc)
			if st, ok := doc["streams"].(map[string]any); ok && st["state"] == want {
				return st
			}
		}
		time.Sleep(time.Millisecond)
	}
	t.Fatalf("item %s streams state never reached %q (timeout %v)", id, want, timeout)
	return nil
}

// packRecord collects what a fake PackItem seam received.
type packRecord struct {
	itemID, absPath string
	ffprobe         map[string]any
	voiceovers      []string
	calls           int32
}

// packSeam returns a Deps.PackItem func-field over the record: it counts calls,
// captures its inputs, sleeps delay, and returns outcome/err.
func packSeam(rec *packRecord, delay time.Duration, outcome pack.PackOutcome, err error) func(context.Context, string, string, map[string]any, []string) (pack.PackOutcome, error) {
	return func(_ context.Context, itemID, absPath string, ffprobe map[string]any, voiceovers []string) (pack.PackOutcome, error) {
		atomic.AddInt32(&rec.calls, 1)
		rec.itemID, rec.absPath, rec.ffprobe, rec.voiceovers = itemID, absPath, ffprobe, voiceovers
		if delay > 0 {
			time.Sleep(delay)
		}
		return outcome, err
	}
}

// TestStreamsLane is the spec floor for "Packaging work rides the enrichment
// queue" (both scenarios) and "Failed pack cools down flat": the lane drains
// under lease semantics, records pack_failed ledger rows under __streams__
// with a flat 30-day cooldown, and never moves metadata-completion state.
func TestStreamsLane(t *testing.T) {
	ctx := context.Background()

	t.Run("success_persists_streams_and_keeps_metadata", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		before := streamsItem(t, s, libID, "i_pack_ok")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, pack.PackOutcome{Playlist: "/media/i_pack_ok/ab12cd34/index.m3u8", Nonce: "ab12cd34"}, nil)}, QueueConfig{})
		q.workStreams(ctx, "i_pack_ok")

		st := streamsState(t, s, "i_pack_ok", "complete", time.Second)
		if st["playlist"] != "/media/i_pack_ok/ab12cd34/index.m3u8" || st["nonce"] != "ab12cd34" {
			t.Fatalf("persisted streams = %v, want the pack.PackOutcome pointer", st)
		}
		// A codec-less outcome (playback-capability-gate D2) persists as an
		// absent key — never an empty array.
		if _, ok := st["codecs"]; ok {
			t.Fatalf("persisted streams carries codecs %v, want an absent key on a codec-less outcome", st["codecs"])
		}
		// A layout-less outcome (fix-tv-unblock-2 Interfaces 1) persists as an
		// absent key too — absence is the fail-open signal the SPA reads.
		if _, ok := st["layout"]; ok {
			t.Fatalf("persisted streams carries layout %v, want an absent key on a layout-less outcome", st["layout"])
		}
		// The seam received the item id, the stamped absolute path, and the
		// stored ffprobe facts (Interface 2 wiring). The fixture carries no
		// audio sidecars, so the voiceover facts are empty.
		if rec.itemID != "i_pack_ok" || rec.absPath != "/library/Movies/Hostile Container.mkv" || rec.ffprobe == nil || rec.voiceovers != nil {
			t.Fatalf("PackItem inputs = %+v, want id + absolute_path + ffprobe + no voiceovers", rec)
		}
		// Metadata completion is unaffected: status ready, namespaces as before.
		it := mustGetItem(t, s, "i_pack_ok")
		if it.Status != statusReady {
			t.Fatalf("status = %q, want untouched %q", it.Status, statusReady)
		}
		assertMetadataUntouched(t, before.Document, it.Document)
		// Success clears (never writes) the pack ledger row.
		rows, _ := s.ListFailures(ctx)
		for _, r := range rows {
			if r.ItemID == "i_pack_ok" && r.PluginID == streamsLaneID {
				t.Fatalf("pack ledger row written on success: %+v", r)
			}
		}
	})

	// The recorded codec record rides the completion write (playback-capability-
	// gate D2): doc["streams"].codecs, in the pack.PackOutcome's rendition order.
	t.Run("success_persists_recorded_codecs", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_cdc")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, pack.PackOutcome{
			Playlist: "/media/i_pack_cdc/ab12cd34/index.m3u8",
			Nonce:    "ab12cd34",
			Codecs:   []string{"avc1.640029", "mp4a.40.2"},
		}, nil)}, QueueConfig{})
		q.workStreams(ctx, "i_pack_cdc")

		st := streamsState(t, s, "i_pack_cdc", "complete", time.Second)
		got, ok := st["codecs"].([]any)
		if !ok || len(got) != 2 || got[0] != "avc1.640029" || got[1] != "mp4a.40.2" {
			t.Fatalf("persisted codecs = %v, want the pack.PackOutcome record in rendition order", st["codecs"])
		}
	})

	// The layout record rides the completion write (fix-tv-unblock-2
	// Interfaces 1): doc["streams"].layout, the lane's layoutName vocabulary
	// verbatim ("single-variant" | "rendition") — the string the SPA
	// compares.
	t.Run("success_persists_layout_when_recorded", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_layout")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, pack.PackOutcome{
			Playlist: "/media/i_pack_layout/ab12cd34/index.m3u8",
			Nonce:    "ab12cd34",
			Layout:   "rendition",
		}, nil)}, QueueConfig{})
		q.workStreams(ctx, "i_pack_layout")

		st := streamsState(t, s, "i_pack_layout", "complete", time.Second)
		if st["layout"] != "rendition" {
			t.Fatalf("persisted layout = %v, want the pack.PackOutcome's layoutName value verbatim", st["layout"])
		}
	})

	t.Run("pack_seam_carries_document_order_audio_sidecars", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		doc := baseDoc("Movies/Hostile Container.mkv")
		doc["parsed"].(map[string]any)["absolute_path"] = "/library/Movies/Hostile Container.mkv"
		doc["parsed"].(map[string]any)["sidecars"] = []any{
			map[string]any{"relative_path": "Rus subs/ep01.srt", "kind": "subtitle", "language": "rus"},
			map[string]any{"relative_path": "Rus sound/ep01.mka", "kind": "audio", "language": "rus"},
			map[string]any{"relative_path": "Rus sound/ep01.2.mka", "kind": "audio"},
		}
		doc["parsed"].(map[string]any)["series_sidecars"] = []any{
			map[string]any{"relative_path": "OST/theme.flac", "kind": "audio"},
		}
		b, _ := json.Marshal(doc)
		if err := s.PutItem(ctx, store.Item{
			ID: "i_pack_vo", ModuleID: "tv", LibraryID: libID, FileID: "i_pack_vo",
			RelativePath: "Movies/Hostile Container.mkv", MediaType: "tv",
			Document: b, Status: statusReady,
		}); err != nil {
			t.Fatalf("PutItem: %v", err)
		}

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, pack.PackOutcome{Playlist: "/p", Nonce: "n"}, nil)}, QueueConfig{})
		q.workStreams(ctx, "i_pack_vo")

		// Only the episode-linked AUDIO sidecars pass, in document order, as
		// absolute paths derived from the episode's stored facts — the
		// subtitle and the serial-level OST never ride the seam.
		want := []string{
			"/library/Rus sound/ep01.mka",
			"/library/Rus sound/ep01.2.mka",
		}
		if len(rec.voiceovers) != len(want) {
			t.Fatalf("voiceovers = %v, want %v", rec.voiceovers, want)
		}
		for i := range want {
			if rec.voiceovers[i] != want[i] {
				t.Fatalf("voiceovers = %v, want %v", rec.voiceovers, want)
			}
		}
	})

	t.Run("terminal_failure_records_flat_pack_failed", func(t *testing.T) {
		withFixedClock(t, time.Date(2026, 8, 3, 12, 0, 0, 0, time.UTC))
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		before := streamsItem(t, s, libID, "i_pack_fail")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, pack.PackOutcome{}, errors.New("ffmpeg exploded"))}, QueueConfig{Backoff: time.Millisecond})
		q.workStreams(ctx, "i_pack_fail")

		st := streamsState(t, s, "i_pack_fail", "failed", time.Second)
		if st["failed_at"] == "" {
			t.Fatalf("failed streams doc missing failed_at: %v", st)
		}
		row := packLedgerRow(t, s, "i_pack_fail")
		if row.Status != ledgerPackFailed {
			t.Fatalf("ledger status = %q, want %q", row.Status, ledgerPackFailed)
		}
		want := now().Add(defaultNoDataCool)
		if row.NextEligibleAt.Before(now().Add(defaultNoDataCool-time.Second)) || row.NextEligibleAt.After(now().Add(defaultNoDataCool+time.Second)) {
			t.Fatalf("NextEligibleAt = %v, want ~now+30d flat (%v)", row.NextEligibleAt, want)
		}
		// A repeated failure shortly after must NOT double the cooldown (the
		// play-time retry re-enqueues; doubling would punish explicit retries).
		q.workStreams(ctx, "i_pack_fail")
		row2 := packLedgerRow(t, s, "i_pack_fail")
		if !row2.NextEligibleAt.Equal(row.NextEligibleAt) {
			t.Fatalf("second failure NextEligibleAt = %v, first = %v (cooldown must stay flat)", row2.NextEligibleAt, row.NextEligibleAt)
		}
		if row2.Attempts != row.Attempts+1 {
			t.Fatalf("attempts = %d, want %d (rounds distinguishable)", row2.Attempts, row.Attempts+1)
		}
		// Metadata completion is unaffected on the failure path too.
		it := mustGetItem(t, s, "i_pack_fail")
		if it.Status != statusReady {
			t.Fatalf("status = %q, want untouched %q", it.Status, statusReady)
		}
		assertMetadataUntouched(t, before.Document, it.Document)
	})

	t.Run("lease_held_for_the_duration_of_the_run", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_lease")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 40*time.Millisecond, pack.PackOutcome{Playlist: "/p", Nonce: "n"}, nil)}, QueueConfig{LeaseTTL: time.Minute})
		var wg sync.WaitGroup
		start := make(chan struct{})
		for i := 0; i < 2; i++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				<-start
				q.workStreams(ctx, "i_pack_lease")
			}()
		}
		close(start)
		wg.Wait()
		if calls := atomic.LoadInt32(&rec.calls); calls != 1 {
			t.Fatalf("PackItem calls = %d, want 1 (the lease serializes the lane within-item)", calls)
		}
	})

	t.Run("long_run_renews_its_lease", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_renew")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 120*time.Millisecond, pack.PackOutcome{Playlist: "/p", Nonce: "n"}, nil)}, QueueConfig{LeaseTTL: 40 * time.Millisecond})

		done := make(chan struct{})
		go func() { defer close(done); q.workStreams(ctx, "i_pack_renew") }()
		time.Sleep(70 * time.Millisecond) // the run has outlived one TTL; renewal must have kept it alive
		if q.leases.acquire("i_pack_renew", "other", time.Minute) {
			t.Fatal("acquire succeeded mid-run — a live long run was treated as dead (renewal broken)")
		}
		<-done
		if !q.leases.acquire("i_pack_renew", "other", time.Minute) {
			t.Fatal("acquire failed after the run ended — the lease was not released")
		}
	})

	t.Run("lane_disabled_is_a_noop", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		before := streamsItem(t, s, libID, "i_pack_off")
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		q.workStreams(ctx, "i_pack_off") // nil PackItem: no panic, no write
		it := mustGetItem(t, s, "i_pack_off")
		var doc map[string]any
		_ = json.Unmarshal(it.Document, &doc)
		if _, ok := doc["streams"]; ok {
			t.Fatalf("disabled lane wrote doc[streams]: %v", doc["streams"])
		}
		_ = before
	})

	t.Run("enqueue_pack_drains_through_the_worker", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_q")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, pack.PackOutcome{Playlist: "/media/i_pack_q/n0/index.m3u8", Nonce: "n0"}, nil)}, QueueConfig{})
		// The fixture item still owes tmdb/frame-grabber metadata work, and the
		// Start sweep derives it; without a resolver the metadata drain would
		// nil-deref at chain.go:61 (races the lane drain, flaking the package).
		// An empty mapResolver marks every metadata source unavailable — the
		// soft, settle-terminal outcome (settle_gate_parity) — leaving the lane
		// drain this subtest exists for.
		q.resolve = mapResolver{}.resolver()
		if err := q.Start(ctx); err != nil {
			t.Fatalf("Start: %v", err)
		}
		defer q.Stop()
		if err := q.EnqueuePack("i_pack_q"); err != nil {
			t.Fatalf("EnqueuePack: %v", err)
		}
		streamsState(t, s, "i_pack_q", "complete", 2*time.Second)
	})
}

// TestPackPolicyRefusal is the acceptance test for the build-time gate
// (playback-capability-gate 1.3, D4): a PackItem seam returning
// refusal.PolicyRefusal — the gate closed between enqueue and build — persists
// state failed with
// the gate's state_reason token and writes NO pack_failed ledger row, so the
// item never enters a cooldown; with the knob on again the frontier's
// eligibility (no CoolUntil — no row exists to read) re-enqueues it and the
// heal run completes, the ledger still empty.
func TestPackPolicyRefusal(t *testing.T) {
	ctx := context.Background()

	t.Run("refusal_persists_failed_without_a_ledger_row", func(t *testing.T) {
		withFixedClock(t, time.Date(2026, 10, 31, 12, 0, 0, 0, time.UTC))
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_policy")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, pack.PackOutcome{}, refusal.PolicyRefusal{Reason: "codec_not_opted_in"})}, QueueConfig{})
		q.workStreams(ctx, "i_pack_policy")

		st := streamsState(t, s, "i_pack_policy", "failed", time.Second)
		// The reason is the BARE gate token — the descriptor's own
		// state_reason spelling (D1), never a wrapped error message.
		if st["reason"] != "codec_not_opted_in" {
			t.Fatalf("reason = %v, want the bare codec_not_opted_in token", st["reason"])
		}
		if st["failed_at"] == "" {
			t.Fatalf("failed streams doc missing failed_at: %v", st)
		}
		rows, err := s.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(rows) != 0 {
			t.Fatalf("ledger rows = %d, want 0 — a policy refusal never charges the cooldown", len(rows))
		}
	})

	t.Run("real_pack_failure_still_records_the_row", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_realfail")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, pack.PackOutcome{}, errors.New("ffmpeg exploded"))}, QueueConfig{})
		q.workStreams(ctx, "i_pack_realfail")

		streamsState(t, s, "i_pack_realfail", "failed", time.Second)
		packLedgerRow(t, s, "i_pack_realfail") // fails the test when absent
	})

	t.Run("knob_on_heals_through_frontier_eligibility", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_pack_heal")

		refused := true
		pack := func(context.Context, string, string, map[string]any, []string) (pack.PackOutcome, error) {
			if refused {
				return pack.PackOutcome{}, refusal.PolicyRefusal{Reason: "codec_not_opted_in"}
			}
			return pack.PackOutcome{Playlist: "/media/i_pack_heal/n1/index.m3u8", Nonce: "n1"}, nil
		}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: pack}, QueueConfig{})
		q.workStreams(ctx, "i_pack_heal")
		streamsState(t, s, "i_pack_heal", "failed", time.Second)

		// Knob on: no ledger row exists, so the frontier's CoolUntil is zero
		// and the re-enqueue reaches the lane; the healed run completes.
		refused = false
		q.resolve = mapResolver{}.resolver()
		if err := q.Start(ctx); err != nil {
			t.Fatalf("Start: %v", err)
		}
		defer q.Stop()
		if err := q.EnqueuePack("i_pack_heal"); err != nil {
			t.Fatalf("EnqueuePack: %v", err)
		}
		st := streamsState(t, s, "i_pack_heal", "complete", 2*time.Second)
		if st["nonce"] != "n1" {
			t.Fatalf("nonce = %v, want the healed build n1", st["nonce"])
		}
		rows, err := s.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(rows) != 0 {
			t.Fatalf("ledger rows = %d, want 0 — the heal needs no ledger to clear", len(rows))
		}
	})
}

// packLedgerRow fetches the item's __streams__ ledger row (fails when absent).
func packLedgerRow(t *testing.T, s *store.Store, itemID string) store.FailureRow {
	t.Helper()
	rows, err := s.ListFailures(context.Background())
	if err != nil {
		t.Fatalf("ListFailures: %v", err)
	}
	for _, r := range rows {
		if r.ItemID == itemID && r.PluginID == streamsLaneID {
			return r
		}
	}
	t.Fatalf("no __streams__ ledger row for %s; rows=%v", itemID, rows)
	return store.FailureRow{}
}

// mustGetItem loads an item or fails the test.
func mustGetItem(t *testing.T, s *store.Store, id string) store.Item {
	t.Helper()
	it, err := s.GetItem(context.Background(), id, access.System())
	if err != nil {
		t.Fatalf("GetItem %s: %v", id, err)
	}
	return it
}

// assertMetadataUntouched asserts the document's metadata-completion namespaces
// (sources, _provenance, _view, _stages) are byte-identical after a lane run —
// the lane's only sanctioned write is the `streams` namespace.
func assertMetadataUntouched(t *testing.T, beforeRaw, afterRaw json.RawMessage) {
	t.Helper()
	var before, after map[string]json.RawMessage
	if err := json.Unmarshal(beforeRaw, &before); err != nil {
		t.Fatalf("unmarshal before: %v", err)
	}
	if err := json.Unmarshal(afterRaw, &after); err != nil {
		t.Fatalf("unmarshal after: %v", err)
	}
	for _, ns := range []string{"sources", "_provenance", "_view", "_stages"} {
		if string(before[ns]) != string(after[ns]) {
			t.Fatalf("metadata namespace %s changed by the streams lane:\nbefore %s\nafter  %s", ns, before[ns], after[ns])
		}
	}
}

// TestStreamsMasterMarker pins the pack-lane rule version (pack-manifest-audio
// 3.1, D5; re-versioned by fix-tv-unblock-2 Interfaces 2): every success
// persist writes `master` as the NUMBER pack.MasterRuleVersion into the streams
// namespace — honest by construction, since every fresh pack (rendition and
// single-variant) is composed at the current rule — while both failure
// persists (real failure and policy refusal) stay version-free, so absence
// (version 0) is the legacy signal the lazy re-heal gate reads. A hand-seeded
// legacy doc (complete + nonce, pre-version shape) reads back marker-absent.
func TestStreamsMasterMarker(t *testing.T) {
	ctx := context.Background()

	t.Run("success_persist_carries_the_rule_version_number", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_master_ok")

		rec := &packRecord{}
		q := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(rec, 0, pack.PackOutcome{Playlist: "/media/i_master_ok/ab12cd34/index.m3u8", Nonce: "ab12cd34"}, nil)}, QueueConfig{})
		q.workStreams(ctx, "i_master_ok")

		st := streamsState(t, s, "i_master_ok", "complete", time.Second)
		// The stored doc round-trips through JSON: the written constant reads
		// back as a float64 — a raw `!=` against int can never hold.
		v, ok := st["master"].(float64)
		if !ok || v != float64(pack.MasterRuleVersion) {
			t.Fatalf("persisted streams = %v, want master: %d (the rule version number) on the success doc", st, pack.MasterRuleVersion)
		}
	})

	t.Run("failure_persists_stay_marker_free", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		streamsItem(t, s, libID, "i_master_fail")
		streamsItem(t, s, libID, "i_master_refuse")

		qFail := NewQueue(Deps{Store: s, Modules: reg, PackItem: packSeam(&packRecord{}, 0, pack.PackOutcome{}, errors.New("ffmpeg exploded"))}, QueueConfig{Backoff: time.Millisecond})
		qFail.workStreams(ctx, "i_master_fail")
		qRefuse := NewQueue(Deps{Store: s, Modules: reg, PackItem: func(context.Context, string, string, map[string]any, []string) (pack.PackOutcome, error) {
			return pack.PackOutcome{}, refusal.PolicyRefusal{Reason: "codec_not_opted_in"}
		}}, QueueConfig{})
		qRefuse.workStreams(ctx, "i_master_refuse")

		for _, id := range []string{"i_master_fail", "i_master_refuse"} {
			st := streamsState(t, s, id, "failed", time.Second)
			if _, ok := st["master"]; ok {
				t.Fatalf("failed streams doc for %s carries master %v, want an absent key — absence is the signal", id, st["master"])
			}
		}
	})

	t.Run("hand_seeded_legacy_doc_reads_marker_absent", func(t *testing.T) {
		s, _ := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		doc := baseDoc("Movies/Legacy Layout.mkv")
		doc["streams"] = map[string]any{"state": "complete", "nonce": "ab12cd34", "playlist": "/media/x/index.m3u8"}
		putItem(t, s, "i_master_legacy", libID, statusReady, doc)

		st := streamsState(t, s, "i_master_legacy", "complete", time.Second)
		if _, ok := st["master"]; ok {
			t.Fatalf("legacy doc carries master %v, want an absent key (it predates the master lane)", st["master"])
		}
	})
}

// settledPackItem seeds a streamsItem whose every queueable tv-module source
// is done (the tmdb namespace added to the streamsItem shape), so Start's
// derivation sweep derives nothing and only lane tasks ride the channels —
// the lane tests observe exactly the tasks they enqueue themselves.
func settledPackItem(t *testing.T, s *store.Store, libID int64, id string) {
	t.Helper()
	it := streamsItem(t, s, libID, id)
	var doc map[string]any
	if err := json.Unmarshal(it.Document, &doc); err != nil {
		t.Fatalf("unmarshal %s document: %v", id, err)
	}
	srcs, ok := doc["sources"].(map[string]any)
	if !ok {
		t.Fatalf("item %s document carries no sources map", id)
	}
	srcs["tmdb"] = map[string]any{"title": "done"}
	srcs["frame-grabber"] = map[string]any{"title": "done"} // the tv seed's 4th queueable source (registry.go)
	b, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("marshal %s document: %v", id, err)
	}
	it.Document = b
	if err := s.PutItem(context.Background(), it); err != nil {
		t.Fatalf("PutItem %s: %v", id, err)
	}
}

// packHold records pack-seam call order and holds the worker on one background
// item — the determinism primitive for the lane tests: started closes when
// the held item enters the seam, release frees it.
type packHold struct {
	mu      sync.Mutex
	order   []string
	started chan struct{}
	release chan struct{}
}

func newPackHold() *packHold {
	return &packHold{started: make(chan struct{}), release: make(chan struct{})}
}

// seam is the Deps.PackItem over the hold: it records call order, blocks on
// holdID until release closes, and answers every call with a canned outcome.
func (h *packHold) seam(holdID string) func(context.Context, string, string, map[string]any, []string) (pack.PackOutcome, error) {
	return func(_ context.Context, itemID, _ string, _ map[string]any, _ []string) (pack.PackOutcome, error) {
		h.mu.Lock()
		h.order = append(h.order, itemID)
		h.mu.Unlock()
		if itemID == holdID {
			close(h.started) // the held item owns the worker
			<-h.release
		}
		return pack.PackOutcome{Playlist: "/media/" + itemID + "/ab12cd34/index.m3u8", Nonce: "ab12cd34"}, nil
	}
}

// calls snapshots the recorded order.
func (h *packHold) calls() []string {
	h.mu.Lock()
	defer h.mu.Unlock()
	return append([]string(nil), h.order...)
}

// parkedQueue starts a one-worker queue over settled items and parks its only
// worker inside the seam on background item holdID (signaled on h.started,
// held until h.release closes) — the test then owns both lanes undisturbed.
func parkedQueue(t *testing.T, s *store.Store, reg *module.Registry, h *packHold, holdID string) *Queue {
	t.Helper()
	q := NewQueue(Deps{Store: s, Modules: reg, PackItem: h.seam(holdID)}, QueueConfig{Workers: 1})
	if err := q.Start(context.Background()); err != nil {
		t.Fatalf("Start: %v", err)
	}
	if err := q.EnqueuePack(holdID); err != nil {
		t.Fatalf("EnqueuePack %s: %v", holdID, err)
	}
	<-h.started
	return q
}

// TestEnqueuePackUrgent is the preferred lane's enqueue contract: accepted
// when free, refused with an error when full or stopped, and nothing buffered
// on a refusal — the shared buffer is never touched.
func TestEnqueuePackUrgent(t *testing.T) {
	ctx := context.Background()

	t.Run("accepted_when_free", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		settledPackItem(t, s, libID, "i_bg")
		h := newPackHold()
		q := parkedQueue(t, s, reg, h, "i_bg")

		if err := q.EnqueuePackUrgent("i_urgent"); err != nil {
			t.Fatalf("EnqueuePackUrgent: %v", err)
		}
		select {
		case got := <-q.urgent:
			if got.rowID != "i_urgent" || !got.streams {
				t.Fatalf("urgent lane task = %+v, want {i_urgent streams}", got)
			}
		default:
			t.Fatal("urgent lane empty after EnqueuePackUrgent — the task was not buffered")
		}

		close(h.release)
		q.Stop()
	})

	t.Run("full_lane_refuses_and_spills_nothing", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		settledPackItem(t, s, libID, "i_bg")
		h := newPackHold()
		q := parkedQueue(t, s, reg, h, "i_bg")

		for i := 0; i < urgentCapacity; i++ {
			if err := q.EnqueuePackUrgent(fmt.Sprintf("i_u_%02d", i)); err != nil {
				t.Fatalf("urgent enqueue %d: %v", i, err)
			}
		}
		if err := q.EnqueuePackUrgent("i_overflow"); err == nil {
			t.Fatal("EnqueuePackUrgent over a full lane returned nil, want the drop-on-full error")
		}
		if len(q.urgent) != urgentCapacity {
			t.Fatalf("urgent lane holds %d, want exactly %d — nothing buffered on refusal", len(q.urgent), urgentCapacity)
		}
		if len(q.work) != 0 {
			t.Fatalf("shared buffer holds %d, want 0 — a refused urgent pack never spills", len(q.work))
		}

		close(h.release)
		q.Stop()
	})

	t.Run("stopped_queue_refuses", func(t *testing.T) {
		s, reg := queueTestStore(t)
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		if err := q.EnqueuePackUrgent("i_x"); err == nil {
			t.Fatal("EnqueuePackUrgent on a never-started queue returned nil, want an error")
		}
		if err := q.Start(ctx); err != nil {
			t.Fatalf("Start: %v", err)
		}
		q.Stop()
		if err := q.EnqueuePackUrgent("i_x"); err == nil {
			t.Fatal("EnqueuePackUrgent on a stopped queue returned nil, want an error")
		}
	})
}

// TestUrgentLanePreferred is the play-priority dispatch scenario: with the
// shared buffer backlogged behind a parked worker, one urgent pack dispatches
// ahead of the backlog's head.
func TestUrgentLanePreferred(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	for _, id := range []string{"i_bg_0", "i_bg_1", "i_bg_2", "i_bg_3", "i_bg_4", "i_urgent"} {
		settledPackItem(t, s, libID, id)
	}
	h := newPackHold()
	q := parkedQueue(t, s, reg, h, "i_bg_0") // the lone worker is now held inside the seam on i_bg_0

	for _, id := range []string{"i_bg_1", "i_bg_2", "i_bg_3", "i_bg_4"} { // the backlog
		if err := q.EnqueuePack(id); err != nil {
			t.Fatalf("backlog enqueue %s: %v", id, err)
		}
	}
	if err := q.EnqueuePackUrgent("i_urgent"); err != nil {
		t.Fatalf("urgent enqueue: %v", err)
	}
	close(h.release)

	var calls []string
	deadline := time.Now().Add(2 * time.Second)
	for len(calls) < 2 {
		calls = h.calls()
		if time.Now().After(deadline) {
			t.Fatalf("packs never dispatched after release; order = %v", calls)
		}
		time.Sleep(time.Millisecond)
	}
	if calls[0] != "i_bg_0" || calls[1] != "i_urgent" {
		t.Fatalf("dispatch order = %v, want i_bg_0 then i_urgent ahead of the backlog head i_bg_1", calls)
	}

	q.Stop()
}

// waitWorkerParked polls runtime.Stack until the queue's worker goroutine is
// parked in its lane receive — the deterministic park barrier for the
// idle-queue test (bounded poll, no sleeps-for-correctness): on the pre-fix
// loop the park is the bare shared receive (goroutine status [chan receive]),
// on the amended loop it is the blocking lane select ([select]). Either is
// the parked state the urgent send must wake.
func waitWorkerParked(t *testing.T) {
	t.Helper()
	deadline := time.Now().Add(2 * time.Second)
	buf := make([]byte, 1<<20)
	for {
		n := runtime.Stack(buf, true)
		for _, g := range bytes.Split(buf[:n], []byte("\n\n")) {
			if !bytes.Contains(g, []byte("internal/enrich.(*Queue).worker")) {
				continue
			}
			if bytes.Contains(g, []byte("[chan receive]")) || bytes.Contains(g, []byte("[select]")) {
				return
			}
		}
		if time.Now().After(deadline) {
			t.Fatalf("queue worker never parked in its lane receive; stacks:\n%s", buf[:n])
		}
		time.Sleep(time.Millisecond)
	}
}

// TestUrgentLaneWakesIdleWorker is the idle-queue invariant (D4, the joint
// 5.1 finding): with the queue idle — derivation deriving nothing, the shared
// buffer empty, and the worker parked in its lane receive — one
// EnqueuePackUrgent dispatches without any shared-lane work arriving. The
// play never waits on background traffic to be discovered.
func TestUrgentLaneWakesIdleWorker(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, _ := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	settledPackItem(t, s, libID, "i_urgent")
	h := newPackHold()
	// the hold id matches nothing the test enqueues, so the seam only records
	// call order and never blocks.
	q := NewQueue(Deps{Store: s, Modules: reg, PackItem: h.seam("i_never_held")}, QueueConfig{Workers: 1})
	if err := q.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer q.Stop()

	waitWorkerParked(t)
	if err := q.EnqueuePackUrgent("i_urgent"); err != nil {
		t.Fatalf("EnqueuePackUrgent: %v", err)
	}

	var calls []string
	deadline := time.Now().Add(2 * time.Second)
	for len(calls) < 1 {
		calls = h.calls()
		if time.Now().After(deadline) {
			t.Fatalf("urgent pack never dispatched to the idle worker (parked in its lane receive, no shared work to wake it); seam calls = %v — the joint 5.1 finding", calls)
		}
		time.Sleep(time.Millisecond)
	}
	if calls[0] != "i_urgent" {
		t.Fatalf("seam calls = %v, want [i_urgent]", calls)
	}
}
